// Decision 7 Stage A operator-filled templates (pure; NO CLI, filesystem, process, or
// environment access). Shared by operator-harness.mjs (which writes them) and the
// summarizer test (which parses buildOperatorTemplate's real output). Keeping them here
// lets the test exercise the exact generated bytes without importing the side-effectful
// harness entrypoint.

import { REQUIRED_REPETITIONS } from "./decision7-lib.mjs";

export function buildOperatorTemplate(runId, caseId, repetition) {
  return [
    "# Decision 7 Stage A - operator observations (EDITABLE).",
    "# Machine-authoritative facts live in ../raw/result.machine.json. Do NOT copy them here.",
    "# Eligibility is a MATRIX-level conclusion (three consecutive eligible runs per required",
    "# host configuration), enforced by summarize-matrix.mjs - never asserted in this file.",
    "run:",
    `  runId: ${runId}`,
    `  matrixCaseId: ${caseId}`,
    `  repetition: ${repetition}`,
    `  requiredRepetitions: ${REQUIRED_REPETITIONS}`,
    "operator:",
    "  name: TO_BE_FILLED",
    "  completed_at: TO_BE_FILLED            # millisecond-precision UTC, e.g. 2026-08-04T13:45:07.123Z; not earlier than the final recorded harness event",
    "  batch_prompt_observed: TO_BE_FILLED   # yes | no | indeterminate",
    "  unexpected_console_behavior: TO_BE_FILLED   # free text; enter 'none' if nothing unexpected occurred",
    "  wrapper_completion_confirmed: TO_BE_FILLED   # clean_exit | batch_prompt_then_exit | batch_prompt_hang | wrapper_hang_without_prompt | indeterminate",
    "  run_verdict: TO_BE_FILLED             # eligible_candidate | blocked | indeterminate",
    "  notes: TO_BE_FILLED                   # free text; enter 'none' if there is nothing to add",
    "",
  ].join("\n");
}

export function buildConsoleTemplate() {
  return [
    "Decision 7 Stage A - console observation (operator-filled)",
    "",
    "Child stdio was inherited by the operator console and was NOT captured by the harness",
    "(raw/metadata.json: environment.consoleOutputCapturedByHarness = false).",
    "",
    "Operator-observed output:",
    "TO BE FILLED",
    "",
    'Batch termination prompt ("Terminate batch job (Y/N)?") observed:',
    "TO BE FILLED",
    "",
    "Screenshot or terminal capture reference:",
    "TO BE FILLED",
    "",
  ].join("\n");
}
